CREATE DATABASE IF NOT EXISTS db_mundial2026 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_mundial2026;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS partidos; DROP TABLE IF EXISTS jugadores; DROP TABLE IF EXISTS equipos; DROP TABLE IF EXISTS sedes;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE sedes (idSede INT AUTO_INCREMENT PRIMARY KEY, sede VARCHAR(100) NOT NULL, ciudad VARCHAR(100) NOT NULL, pais VARCHAR(50) NOT NULL, capacidad INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE equipos (idEquipo INT AUTO_INCREMENT PRIMARY KEY, equipo VARCHAR(80) NOT NULL, grupo CHAR(1) NULL, confederacion VARCHAR(20) NOT NULL) ENGINE=InnoDB;
CREATE TABLE jugadores (idJugador INT AUTO_INCREMENT PRIMARY KEY, jugador VARCHAR(100) NOT NULL, posicion VARCHAR(50) NOT NULL, dorsal INT NULL, edad INT NULL, club VARCHAR(100) NOT NULL, equipo_id INT NOT NULL, CONSTRAINT fk_jugador_equipo FOREIGN KEY (equipo_id) REFERENCES equipos(idEquipo) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE partidos (idPartido INT AUTO_INCREMENT PRIMARY KEY, fase VARCHAR(50) NOT NULL DEFAULT 'Fase de grupos', fecha DATETIME NULL, sede_id INT NULL, equipo_local_id INT NOT NULL, equipo_visitante_id INT NOT NULL, goles_local INT NOT NULL DEFAULT 0, goles_visitante INT NOT NULL DEFAULT 0, estado VARCHAR(20) NOT NULL DEFAULT 'Programado', CONSTRAINT fk_partido_sede FOREIGN KEY(sede_id) REFERENCES sedes(idSede) ON DELETE SET NULL, CONSTRAINT fk_partido_local FOREIGN KEY(equipo_local_id) REFERENCES equipos(idEquipo) ON DELETE CASCADE, CONSTRAINT fk_partido_visitante FOREIGN KEY(equipo_visitante_id) REFERENCES equipos(idEquipo) ON DELETE CASCADE) ENGINE=InnoDB;
